// Monta a entrada da seção 4.2 a partir do formulário do site. O id externo é o UUID gerado neste envio, e o lead do site nunca é de teste.
const corpo = $json.body || {};
function texto(valor) {
  if (valor === undefined || valor === null || typeof valor === 'object') return null;
  const limpo = String(valor).trim();
  return limpo ? limpo : null;
}

// Os campos conhecidos vão para o lugar deles; a mensagem e os outros campos preenchidos, para as respostas extras.
const conhecidos = ['nome', 'email', 'telefone', 'empresa', 'uf', 'mensagem', 'utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'gclid', 'website'];
const respostasExtras = {};
if (texto(corpo.mensagem)) respostasExtras['Mensagem'] = texto(corpo.mensagem);
for (const campo of Object.keys(corpo)) {
  if (!conhecidos.includes(campo) && texto(corpo[campo])) respostasExtras[campo] = texto(corpo[campo]);
}

const utm = { source: texto(corpo.utm_source), medium: texto(corpo.utm_medium), campaign: texto(corpo.utm_campaign), content: texto(corpo.utm_content), term: texto(corpo.utm_term) };
const temUtm = Object.values(utm).some(function (valor) { return valor !== null; });

return {
  json: {
    lead: {
      origem: 'site',
      idExterno: $json.idExterno,
      recebidoEm: $now.toUTC().toISO(),
      teste: false,
      nome: texto(corpo.nome),
      email: texto(corpo.email),
      telefone: texto(corpo.telefone),
      empresa: texto(corpo.empresa),
      uf: texto(corpo.uf),
      plataforma: 'site',
      utm: temUtm ? utm : null,
      gclid: texto(corpo.gclid),
      respostasExtras: Object.keys(respostasExtras).length ? respostasExtras : null,
    },
  },
};

// Classifica a falha do envio ao CRM (seção 4.5). Guarda só o código ou o tipo da falha, nunca o corpo da resposta, que pode ter dados pessoais.
// A regra do destino é a mesma nos fluxos de entrada e no reenvio, e o FluxosN8nTests confere que o texto dela é igual nos quatro.
function destinoDaFalha(codigo) {
  // A recusa da própria entrada: tentar de novo não resolve, e ela vai para as recusadas.
  if (codigo === '400' || codigo === '413') return 'recusada';
  // O CRM fora do ar, lento ou no limite de requisições: o reenvio tenta de novo, sem e-mail.
  if (codigo === '' || codigo === '408' || codigo === '429' || /^5[0-9]{2}$/.test(codigo)) return 'temporaria';
  // A chave ou o endereço do CRM (401, 403, 404) e qualquer outro código: a entrada espera na fila, e o admin corrige.
  return 'configuracao';
}

const erro = $json.error || {};
const mensagem = String(erro.message || '');
const prefixo = /^([0-9]{3}) - /.exec(mensagem);
const bruto = String(erro.httpCode || erro.status || erro.statusCode || (prefixo ? prefixo[1] : ''));
const codigo = /^[0-9]{3}$/.test(bruto) ? bruto : '';

let ultimoErro;
if (codigo) {
  ultimoErro = 'HTTP ' + codigo;
} else if (/timeout|timed out|ETIMEDOUT|ECONNABORTED/i.test(String(erro.code || '') + ' ' + mensagem)) {
  ultimoErro = 'Tempo esgotado (10 s)';
} else {
  ultimoErro = 'Falha de conexão';
}

// Nas recusadas, o corpo vai inteiro só até 8 KB; acima disso, os primeiros 8 KB, e o detalhe guarda o tamanho original. Num 413,
// vai sem o corpo. As Data Tables dividem um teto de 200 MiB, e o webhook do site é público.
const LIMITE_GUARDADO = 8 * 1024;
const lead = $('Montar o lead').item.json.lead;
const corpo = JSON.stringify(lead);
const tamanho = Buffer.byteLength(corpo, 'utf8');
let guardado = corpo;
if (codigo === '413') {
  guardado = '';
} else if (tamanho > LIMITE_GUARDADO) {
  guardado = Buffer.from(corpo, 'utf8').subarray(0, LIMITE_GUARDADO).toString('utf8').replace(/�$/, '');
}
const cortado = guardado !== '' && guardado.length < corpo.length;

return {
  json: {
    destino: destinoDaFalha(codigo),
    ultimoErro: ultimoErro,
    lead: lead,
    payloadRecusada: guardado,
    detalheRecusada: ultimoErro + ', entrada de ' + tamanho + ' bytes' + (cortado ? ', guardados os primeiros 8 KB' : ''),
  },
};

// Mede a entrada em bytes, como o CRM conta o limite do corpo: 64 KB (seção 4.2). Acima dele, a entrada nem vai ao CRM nem entra
// na fila: fica nas recusadas, sem o corpo, só com o tamanho. O webhook do site é público, o n8n aceita corpos de até 16 MiB, e
// as Data Tables dividem um teto de 200 MiB.
const LIMITE_DO_CRM = 64 * 1024;
const tamanho = Buffer.byteLength(JSON.stringify($json.lead), 'utf8');
return { json: { ...$json, tamanho: tamanho, cabeNoCrm: tamanho <= LIMITE_DO_CRM } };

// Conta a posição deste envio na última hora e nas últimas 24 horas (seção 4.5): os envios com o id até o da linha dele, que o
// "Registrar o envio" acabou de gravar. Com envios ao mesmo tempo, cada um tem a sua posição, e só um é o primeiro acima do
// limite. As datas são comparadas aqui, e não no filtro da Data Table, que no n8n local compara texto.
const saida = (no, indice) => {
  try {
    return $(no).all(indice);
  } catch (erro) {
    return [];
  }
};
// Com a busca em erro, o n8n manda o erro para a saída de erro e, pelo "Always Output Data", um item vazio para cá. Quem leva o
// envio ao CRM é então o "Seguir sem o limite", e este caminho para, para o envio não ir duas vezes.
if (saida('Buscar os envios recentes', 1).length > 0) return [];
const meu = $('Registrar o envio').first().json;
if (typeof meu.id !== 'number') {
  // Em algumas falhas, como uma coluna que não existe, o nó de Data Table devolve o item de entrada, sem erro e sem o id. O erro
  // daqui leva o envio ao "Seguir sem o limite".
  throw new Error('A gravação na crm_envios_site não devolveu a linha');
}
const configuracao = $('Configuração').first().json;
const porHora = Number(configuracao.limiteSitePorHora);
const porDia = Number(configuracao.limiteSitePorDia);
const momento = DateTime.fromJSDate(new Date(meu.criado_em));
const datas = $input
  .all()
  .map((item) => item.json)
  .filter((linha) => linha.id !== undefined && linha.id <= meu.id)
  .map((linha) => DateTime.fromJSDate(new Date(linha.criado_em)));
const naHora = datas.filter((data) => data > momento.minus({ hours: 1 })).length;
const noDia = datas.filter((data) => data > momento.minus({ days: 1 })).length;
const acimaDaHora = naHora > porHora;
const acimaDoDia = noDia > porDia;

// O envio barrado fica nas recusadas com no máximo os primeiros 8 KB do lead e, acima dos 64 KB do CRM, sem o corpo, como as
// outras recusadas. O detalhe começa pelo limite que barrou: o "Decidir o aviso" lê esse começo.
const LIMITE_GUARDADO = 8 * 1024;
const LIMITE_DO_CRM = 64 * 1024;
const lead = $('Montar o lead').first().json.lead;
const corpo = JSON.stringify(lead);
const tamanho = Buffer.byteLength(corpo, 'utf8');
let guardado = corpo;
if (tamanho > LIMITE_DO_CRM) {
  guardado = '';
} else if (tamanho > LIMITE_GUARDADO) {
  guardado = Buffer.from(corpo, 'utf8').subarray(0, LIMITE_GUARDADO).toString('utf8').replace(/�$/, '');
}
const cortado = guardado !== '' && guardado.length < corpo.length;
const qual = acimaDaHora && acimaDoDia ? 'Acima dos limites da hora e do dia' : acimaDaHora ? 'Acima do limite da hora' : 'Acima do limite do dia';
const contagens = naHora + ' envios na última hora (limite ' + porHora + ') e ' + noDia + ' nas últimas 24 horas (limite ' + porDia + ')';

return [
  {
    json: {
      lead: lead,
      dentroDoLimite: !acimaDaHora && !acimaDoDia,
      cruzouHora: naHora === porHora + 1,
      cruzouDia: noDia === porDia + 1,
      momento: momento.toISO(),
      contagens: contagens,
      payloadRecusada: guardado,
      detalheRecusada:
        qual + ': ' + contagens + ', entrada de ' + tamanho + ' bytes' + (tamanho > LIMITE_DO_CRM ? ', sem o corpo' : cortado ? ', guardados os primeiros 8 KB' : ''),
    },
    pairedItem: { item: 0 },
  },
];

// O limite nunca perde um lead (seção 4.5): se falhar a gravação ou a busca na crm_envios_site, a conta do limite ou a recusa do
// envio barrado, o envio segue para o CRM sem o limite. O "Marcar a falha do limite" grava a falha nas recusadas, para o aviso, no
// máximo um por dia, e para o resumo diário. Uma gravação que falhou não devolve a linha com o id. Sem o índice, o $() leria a
// saída que liga o nó a este, que é a de erro.
const saida = (no, indice) => {
  try {
    return $(no).all(indice);
  } catch (erro) {
    return [];
  }
};
const gravou = saida('Registrar o envio', 0).some((item) => typeof item.json.id === 'number');
const passo = $('Recusar pelo limite').isExecuted
  ? 'a gravação do envio barrado nas recusadas'
  : !gravou
    ? 'a gravação na crm_envios_site'
    : saida('Buscar os envios recentes', 1).length > 0
      ? 'a busca na crm_envios_site'
      : 'a conta do limite';
return [
  {
    json: { lead: $('Montar o lead').first().json.lead, dentroDoLimite: true, momento: DateTime.now().toISO(), passoQueFalhou: passo },
    pairedItem: { item: 0 },
  },
];

// Decide o aviso ao admin, sem nenhum dado das entradas (seção 4.5). O do limite sai para o envio que cruzou o limite, se nenhum
// outro foi barrado pelo mesmo limite antes dele: na última hora, o da hora; nas últimas 24 horas, o do dia. O da falha sai no
// máximo uma vez por dia. Só contam as linhas de antes deste envio: as de um envio ao mesmo tempo, gravadas depois, ficam de fora.
// O "Conferir o limite" chega aqui pelas duas saídas, e o $() vai com o índice: sem ele, leria a de erro.
const saida = (no, indice) => {
  try {
    return $(no).all(indice);
  } catch (erro) {
    return [];
  }
};
// Com a busca das recusadas em erro, não dá para saber se o aviso já saiu: ele não sai, para nunca mandar um e-mail por envio.
if (saida('Buscar os avisos', 1).length > 0) return [];
const falha = $('Seguir sem o limite').isExecuted;
const origem = falha ? $('Seguir sem o limite').first(0).json : $('Conferir o limite').first(0).json;
const momento = DateTime.fromISO(origem.momento);
const linhas = $input
  .all()
  .map((item) => item.json)
  .filter((linha) => linha.id !== undefined);
const houveAntes = (horas, condicao) =>
  linhas.some((linha) => {
    const data = DateTime.fromJSDate(new Date(linha.criado_em));
    return condicao(linha) && data < momento && data > momento.minus({ hours: horas });
  });

let avisar;
let assunto;
let texto;
if (falha) {
  // Sem a marca gravada, o aviso não sai: assim, nem uma falha das recusadas manda um e-mail por envio.
  const marcou = saida('Marcar a falha do limite', 0).some((item) => typeof item.json.id === 'number' && item.json.tipo === 'site_sem_limite');
  avisar = marcou && !houveAntes(24, (linha) => linha.tipo === 'site_sem_limite');
  assunto = '[CRM] O limite de envios do site falhou';
  texto = [
    'O fluxo ' + $workflow.name + ' não conseguiu aplicar o limite de envios do site: falhou ' + origem.passoQueFalhou + '.',
    '',
    'O envio foi ao CRM sem o limite, e os próximos também vão enquanto a falha continuar. Confira se a Data Table crm_envios_site existe, com a coluna criado_em, e se a crm_entradas_recusadas está como no README (n8n local).',
    '',
    'Este aviso sai no máximo uma vez por dia, e o resumo diário conta as falhas. Ele não traz os dados das entradas.',
  ].join('\n');
} else {
  // O detalhe da recusa começa pelo limite que barrou: "Acima do limite da hora", "Acima do limite do dia" ou os dois.
  const barradoPor = (trecho) => (linha) =>
    linha.tipo === 'site_acima_do_limite' && String(linha.detalhe || '').split(':')[0].includes(trecho);
  const daHora = origem.cruzouHora && !houveAntes(1, barradoPor('da hora'));
  const doDia = origem.cruzouDia && !houveAntes(24, barradoPor('do dia'));
  avisar = daHora || doDia;
  assunto = '[CRM] O limite de envios do site barrou um envio';
  texto = [
    'O fluxo ' + $workflow.name + ' barrou um envio do site às ' + momento.setZone('America/Sao_Paulo').toFormat('HH:mm') + ': ' + origem.contagens + '. O site recebeu a resposta de sempre, e a entrada não foi ao CRM.',
    '',
    'Os envios barrados ficam 7 dias na Data Table crm_entradas_recusadas, com o tipo site_acima_do_limite e no máximo os primeiros 8 KB da entrada. Se algum for de uma pessoa de verdade, cadastre o lead à mão no CRM. Se o tráfego for de verdade, suba o limiteSitePorHora ou o limiteSitePorDia no nó "Configuração" e publique o fluxo de novo.',
    '',
    'Os próximos envios barrados nesta janela não mandam e-mail, e o resumo diário conta todos. Este e-mail não traz os dados das entradas.',
  ].join('\n');
}
return [{ json: { avisar: avisar, assunto: assunto, texto: texto } }];
